export default function App() {
  const [selectedMarket, setSelectedMarket] = useState("Select Market");
  const [fileData, setFileData] = useState({});
  const [processedResults, setProcessedResults] = useState([]);
  const [statusMessage, setStatusMessage] = useState("");
  const [marketError, setMarketError] = useState("");
  const [filterErrors, setFilterErrors] = useState(false);

  const [summaryStats, setSummaryStats] = useState({
    totalPoles: 0,
    totalNotes: 0,
    totalAnchors: 0,
    totalGuys: 0,
    numDropPoles: 0,
    numPass: 0,
    numError: 0
  });

  const extractNumeric = (val) => String(val || "").replace(/\D/g, "");
  const cleanNumber = (value, fallback = "") => {
    if (value === null || value === undefined || String(value).trim() === "") return fallback;
    const number = Number(value);
    return Number.isFinite(number) ? Number(number.toFixed(2)) : fallback;
  };
  const isDropPole = (textVal) => /\b(DROP|SVC DROP|SERVICE DROP)\b/i.test(String(textVal || ""));

  const extractCircumference = (textVal) => {
    const text = String(textVal || "").replace(/[–—−]/g, "-");
    const match = text.match(/CIRCUMFERENCE\s*[:\-"\s]*\s*(\d+(?:\.\d+)?)/i)
      || text.match(/CIRCUMFERENCE[^\d]*(\d+(?:\.\d+)?)/i);
    return match ? parseFloat(match[1]) : 0;
  };

  const extractAllAttHoa = (textVal) => {
    if (!textVal) return [];
    const text = String(textVal).replace(/[–—−]/g, "-");
    return text
      .split(/\r?\n/)
      .map((line) => {
        if (line.toUpperCase().includes("ATT HOA")) {
          const m = line.match(/ATT\s+HOA\s*[^\d]*(\d+(?:\.\d+)?)/i);
          return m ? parseFloat(m[1]) : null;
        }
        return null;
      })
      .filter((v) => v !== null && v > 0);
  };

  const extractLowestAttHoa = (textVal) => {
    const list = extractAllAttHoa(textVal);
    return list.length > 0 ? Math.min(...list) : 999999;
  };

  const matchSpecies = (actual, expected) => {
    if (!actual) return true;
    const act = actual.toUpperCase();
    const exp = expected.toUpperCase();
    if (act === exp) return true;
    if (exp === "SOUTHERN PINE" && ["SP", "SYP", "SOUTHERN PINE"].includes(act)) return true;
    if (exp === "DOUGLAS FIR" && ["DF", "DOUGLAS FIR"].includes(act)) return true;
    return false;
  };

  const formatModificationUser = (rawUser) => {
    if (!rawUser) return "Unknown User";
    const cleanUser = String(rawUser).trim().toLowerCase();
    return USER_LOOKUP[cleanUser] || "Unknown User";
  };

  const normalizeIqGeoLink = (value) => {
    const text = String(value || "").trim().replace(/&amp;/gi, "&");
    const hyperlinkMatch = text.match(/HYPERLINK\s*\(\s*["'](https?:\/\/[^"']+)["']/i);
    if (hyperlinkMatch) return hyperlinkMatch[1].replace(/[),.;]+$/, "");
    const urlMatch = text.match(/https?:\/\/[^\s<>"']+/i);
    if (urlMatch) return urlMatch[0].replace(/[),.;]+$/, "");
    if (/^www\./i.test(text)) return `https://${text}`;
    return "";
  };

  const buildIqGeoLink = (poleID) => {
    const cleanPoleID = String(poleID || "").trim();
    return cleanPoleID
      ? `https://iqgeo.att.com/myworld/myworld.html#internal_pole/${encodeURIComponent(cleanPoleID)}`
      : "";
  };

  const normalizeColumnName = (value) => String(value || "").toUpperCase().replace(/[^A-Z0-9]/g, "");

  const findColumnIndex = (headerRow, names) => {
    const normalizedNames = names.map(normalizeColumnName);
    return (headerRow || []).findIndex((header) => normalizedNames.includes(normalizeColumnName(header)));
  };

  const findIqLinkInRow = (row, headerRow, poleID) => {
    if (row) {
      if (headerRow) {
        const myworldLinkIndex = headerRow.findIndex((header) => normalizeColumnName(header) === "MYWORLDLINK");
        if (myworldLinkIndex !== -1) {
          const myworldLink = normalizeIqGeoLink(row[myworldLinkIndex]);
          if (myworldLink) return myworldLink;
        }

        for (let c = 0; c < headerRow.length; c++) {
          const head = normalizeColumnName(headerRow[c]);
          if (head.includes("MYWORLD") || head.includes("IQGEO") || head.includes("LINK")) {
            const link = normalizeIqGeoLink(row[c]);
            if (link) return link;
          }
        }
      }

      for (let c = 0; c < row.length; c++) {
        const link = normalizeIqGeoLink(row[c]);
        if (link) return link;
      }
    }

    return buildIqGeoLink(poleID);
  };

  const sheetToRows = (sheet) => {
    const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" });
    const range = XLSX.utils.decode_range(sheet['!ref'] || 'A1');
    return rows.map((row, rowIndex) => {
      const normalized = [...row];
      for (let columnIndex = range.s.c; columnIndex <= range.e.c; columnIndex++) {
        const address = XLSX.utils.encode_cell({ r: rowIndex + range.s.r, c: columnIndex });
        const cell = sheet[address];
        if (cell && cell.l && cell.l.Target) normalized[columnIndex] = cell.l.Target;
        if (cell && cell.f && /HYPERLINK\s*\(/i.test(cell.f)) normalized[columnIndex] = cell.f;
      }
      return normalized;
    });
  };

  const normalizeJsonSheets = (jsonData) => {
    if (Array.isArray(jsonData)) {
      if (!jsonData.length || Array.isArray(jsonData[0])) return { POLE: jsonData };
      const columns = Object.keys(jsonData[0]);
      return { POLE: [columns, ...jsonData.map((item) => columns.map((column) => item[column] ?? ""))] };
    }
    return Object.entries(jsonData || {}).reduce((sheets, [key, value]) => {
      const rows = Array.isArray(value) ? value : [];
      sheets[key.toUpperCase()] = rows.length && !Array.isArray(rows[0])
        ? [Object.keys(rows[0]), ...rows.map((item) => Object.keys(rows[0]).map((column) => item[column] ?? ""))]
        : rows;
      return sheets;
    }, {});
  };

  const findModUserColumnIndex = (headerRow) => {
    if (!headerRow) return -1;
    for (let c = 0; c < headerRow.length; c++) {
      const h = String(headerRow[c] || "").toUpperCase();
      if (h.includes("MODIFICATION") || h.includes("MODIFIED") || h.includes("USER")) {
        return c;
      }
    }
    return -1;
  };

  const handleFileUpload = (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;

    const parsedSheets = { ...fileData };
    let loadedCount = 0;

    files.forEach((file) => {
      const fileName = file.name.toUpperCase();
      const reader = new FileReader();

      reader.onload = (evt) => {
        if (fileName.endsWith('.JSON')) {
          try {
            const jsonData = normalizeJsonSheets(JSON.parse(evt.target.result));
            Object.keys(jsonData).forEach((key) => {
              parsedSheets[key] = jsonData[key];
            });
          } catch (err) {
            alert(`Invalid JSON format in file: ${file.name}`);
          }
        } else if (fileName.endsWith('.CSV')) {
          const wb = XLSX.read(evt.target.result, { type: 'string' });
          const sheetName = wb.SheetNames[0];
          const rows = sheetToRows(wb.Sheets[sheetName]);
          const headers = (rows[0] || []).map(normalizeColumnName);
          let key = "UNKNOWN";
          if (fileName.includes("POLE")) key = "POLE";
          else if (fileName.includes("NOTE")) key = "NOTE";
          else if (fileName.includes("ANCHOR")) key = "ANCHOR";
          else if (fileName.includes("GUY")) key = "GUY";
          else if (headers.includes("MYWORLDLINK") || headers.includes("POLEID") || headers.includes("ID")) key = "POLE";
          else if (headers.includes("CIRCUMFERENCE") || headers.includes("NOTE")) key = "NOTE";
          else if (headers.includes("ANCHOR")) key = "ANCHOR";
          else if (headers.includes("GUY")) key = "GUY";

          parsedSheets[key] = rows;
        } else {
          const wb = XLSX.read(evt.target.result, { type: 'binary' });
          wb.SheetNames.forEach((name) => {
            parsedSheets[name.toUpperCase()] = sheetToRows(wb.Sheets[name]);
          });
        }

        loadedCount++;
        if (loadedCount === files.length) {
          setFileData(parsedSheets);
          setSummaryStats(prev => ({
            ...prev,
            totalPoles: parsedSheets["POLE"] ? Math.max(0, parsedSheets["POLE"].length - 1) : 0,
            totalNotes: parsedSheets["NOTE"] ? Math.max(0, parsedSheets["NOTE"].length - 1) : 0,
            totalAnchors: parsedSheets["ANCHOR"] ? Math.max(0, parsedSheets["ANCHOR"].length - 1) : 0,
            totalGuys: parsedSheets["GUY"] ? Math.max(0, parsedSheets["GUY"].length - 1) : 0
          }));
          setStatusMessage(`Loaded sheet context: ${Object.keys(parsedSheets).join(', ')}`);
        }
      };

      if (fileName.endsWith('.JSON') || fileName.endsWith('.CSV')) {
        reader.readAsText(file);
      } else {
        reader.readAsBinaryString(file);
      }
    });
  };

  const executeQCProcess = () => {
    if (selectedMarket === "Select Market") {
      setMarketError("Please select a market before running the QC check.");
      setStatusMessage("");
      return;
    }

    setMarketError("");
    const wsPole = fileData["POLE"];
    const wsNote = fileData["NOTE"];
    const wsAnchor = fileData["ANCHOR"];
    const wsGuy = fileData["GUY"];

    if (!wsPole || !wsNote) {
      alert("POLE and NOTE sheets/data are required!");
      return;
    }

    const mRule = DEFAULT_MARKET_GUIDELINES[selectedMarket] || {
      exp_anchor: "ANC-EXP-5/8",
      exp_ownership: "FO/CO",
      exp_species: "Southern Pine"
    };

    const isLouisiana = selectedMarket.includes("LOUISIANA");

    const dictNoteD = {}, dictNoteL = {};
    if (wsNote) {
      for (let i = 1; i < wsNote.length; i++) {
        const id = extractNumeric(wsNote[i][10]);
        if (id) {
          dictNoteD[id] = wsNote[i][3] || "";
          dictNoteL[id] = wsNote[i][11] || "";
        }
      }
    }

    const dictAnchor = {};
    if (wsAnchor) {
      for (let i = 1; i < wsAnchor.length; i++) {
        const id = extractNumeric(wsAnchor[i][8]);
        if (id) {
          const q = String(wsAnchor[i][16] || "").trim();
          const j = String(wsAnchor[i][9] || "").trim();
          dictAnchor[id] = (q && j) ? `${q}-${j}` : (j || q);
        }
      }
    }

    const dictGuyA = {}, dictGuyE = {};
    if (wsGuy) {
      for (let i = 1; i < wsGuy.length; i++) {
        const pid = extractNumeric(wsGuy[i][5]);
        if (pid) {
          if (!dictGuyA[pid]) { dictGuyA[pid] = []; dictGuyE[pid] = []; }
          dictGuyA[pid].push(parseFloat(wsGuy[i][0]) || 0);
          dictGuyE[pid].push(String(wsGuy[i][4] || ""));
        }
      }
    }

    let passCount = 0;
    let errorCount = 0;
    let dropCount = 0;
    const results = [];

    const headerRow = wsPole[0];
    const detectedModIdx = findModUserColumnIndex(headerRow);
    const poleIdIdx = findColumnIndex(headerRow, ["POLE ID", "POLEID", "POLE_ID", "ID"]);

    for (let i = 1; i < wsPole.length; i++) {
      const row = wsPole[i];
      if (!row || !row.length) continue;

      const acc = String(row[0] || "").trim().toLowerCase();
      
      // Clean float rounding issue (e.g. 44.99999999999 -> 45)
      const ht = cleanNumber(row[7]);

      const cls = String(row[1] || "").trim();
      let hoaVal = cleanNumber(row[5], 0);
      if (hoaVal) hoaVal = Math.round(hoaVal * 3.28084 * 100) / 100;

      const poleID = String(row[poleIdIdx !== -1 ? poleIdIdx : 8] || "").trim();
      const numID = extractNumeric(poleID);

      let rawModUser = "";
      if (detectedModIdx !== -1 && row[detectedModIdx]) {
        rawModUser = row[detectedModIdx];
      } else if (row[13] || row[14] || row[15]) {
        rawModUser = row[13] || row[14] || row[15];
      }
      const modificationUser = formatModificationUser(rawModUser);

      const rawIqLink = findIqLinkInRow(row, headerRow, poleID);

      let poleText = dictNoteD[numID] || "";
      if (!poleText || poleText.trim().toUpperCase() === "NONE") {
        poleText = dictNoteL[numID] || "";
      }
      const uPoleText = poleText.toUpperCase();

      if (isDropPole(poleText)) {
        dropCount++;
      }

      // Circumference Check (Round e.g., 32.5 -> 33)
      let circCheck = "";
      const rawCirc = extractCircumference(poleText);
      const actualCirc = Math.round(rawCirc);

      if (isDropPole(poleText)) {
        circCheck = "MATCH";
      } else if (!poleText) {
        circCheck = "CHECK POLE & ASSOCIATE NOTE";
      } else if (uPoleText.includes("INACCESSIBLE")) {
        circCheck = acc === "y" ? "Accessible is Yes But Circumference is inaccessible" : "MATCH";
      } else if (acc === "n") {
        circCheck = actualCirc > 0 ? "ERROR: CHECK ACCESSIBILITY" : "MATCH";
      } else if (ht && cls) {
        const lookupHtKey = Math.round(ht);
        const rawExp = DEFAULT_LOOKUP_MATRIX[lookupHtKey] ? DEFAULT_LOOKUP_MATRIX[lookupHtKey][cls] : undefined;
        if (rawExp === undefined) {
          circCheck = "Height/Class Not Found";
        } else {
          const exp = rawExp;
          if (actualCirc === 0) circCheck = "CIRCUMFERENCE MISSING";
          else if (Math.abs(actualCirc - exp) <= 1) circCheck = "MATCH";
          else circCheck = `ERROR: Expected ${exp}, Found ${actualCirc}`;
        }
      }

      // HOA Check
      let hoaCheck = "";
      if (isDropPole(poleText)) {
        hoaCheck = "MATCH";
      } else {
        const minAtt = extractLowestAttHoa(poleText);
        if (minAtt === 999999) hoaCheck = "NO ATT HOA FOUND";
        else if (Math.round(hoaVal) === Math.round(minAtt)) hoaCheck = "MATCH";
        else hoaCheck = `MISMATCH: Col D=${Math.round(hoaVal)} | Min ATT=${Math.round(minAtt)}`;
      }

      // Anchor Check
      let rawAnchorComb = "", isHoaMatched = false;
      if (dictGuyA[numID]) {
        const attHoaList = extractAllAttHoa(poleText);
        dictGuyA[numID].forEach((meters, gIdx) => {
          const guyFt = Math.round(meters * 3.28084);
          if (attHoaList.some((v) => Math.round(v) === guyFt)) {
            isHoaMatched = true;
            const aId = extractNumeric(dictGuyE[numID][gIdx]);
            if (dictAnchor[aId]) rawAnchorComb += (rawAnchorComb ? ", " : "") + dictAnchor[aId];
          }
        });
      }

      let anchorDetailResult = "", isAnchorValid = true;
      if (isHoaMatched && rawAnchorComb) {
        for (let item of rawAnchorComb.split(",")) {
          const clean = item.trim();
          const prefix = clean.substring(0, 2).toUpperCase();
          if (prefix === "Y-" && clean.substring(2).trim().toUpperCase() !== mRule.exp_anchor.toUpperCase()) {
            isAnchorValid = false;
          }
          if (prefix === "N-" && isLouisiana && !["SRW-C7", "SRW-C3", "SRW-C6"].some((c) => clean.substring(2).trim().toUpperCase().startsWith(c))) {
            isAnchorValid = false;
          }
        }
        anchorDetailResult = isAnchorValid ? rawAnchorComb : `Incorrect - ${rawAnchorComb} / Correct is ${mRule.exp_anchor}`;
      }

      const actOwnership = String(row[18] || "").trim().toUpperCase();
      const hasOther = ["POWER HOA", "OTHER HOA", "CATV HOA", "TELCO HOA"].some((k) => uPoleText.includes(k));
      const expOwner = (!hasOther && extractAllAttHoa(poleText).length > 0) ? "CO" : mRule.exp_ownership;
      const isOwnerValid = expOwner.split("/").map((s) => s.trim()).includes(actOwnership) || !actOwnership;

      const actSpecies = String(row[20] || "").trim();
      const isSpeciesValid = matchSpecies(actSpecies, mRule.exp_species);

      const hasError = (circCheck !== "MATCH" || hoaCheck !== "MATCH" || !isAnchorValid || !isOwnerValid || !isSpeciesValid);

      if (hasError) {
        errorCount++;
      } else {
        passCount++;
      }

      results.push({
        rowNum: i + 1,
        accessible: row[0] || "",
        height: ht,
        classVal: row[1] || "",
        hoa: hoaVal,
        poleID: poleID,
        modificationUser: modificationUser,
        iqLink: rawIqLink,
        poleDetails: poleText,
        circCheck,
        hoaCheck,
        anchorDetails: anchorDetailResult,
        ownership: actOwnership,
        isOwnerValid,
        species: actSpecies,
        isSpeciesValid,
        hasError
      });
    }

    setSummaryStats(prev => ({
      ...prev,
      numDropPoles: dropCount,
      numPass: passCount,
      numError: errorCount
    }));

    setProcessedResults(results);
    setStatusMessage(`QC finished for market: ${selectedMarket}`);
  };

  const displayed = filterErrors ? processedResults.filter((r) => r.hasError) : processedResults;

  return (
    <div className="p-6 max-w-7xl mx-auto space-y-6 bg-gray-50 min-h-screen">
      <div className="flex justify-between items-center border-b pb-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">QC Pole Inspector Dashboard</h1>
          <p className="text-xs text-gray-500 mt-1">Supports Excel (.xlsx), Single JSON, or Multiple CSV files</p>
          <p className="text-xs text-gray-500 mt-1">Developed by Shubham Srivastav | shubhamsri505@gmail.com</p>
        </div>
        <select
          value={selectedMarket}
          onChange={(e) => {
            setSelectedMarket(e.target.value);
            setMarketError("");
          }}
          className="p-2 border rounded bg-white text-sm font-medium text-gray-700"
        >
          <option value="Select Market">Select Market</option>
          {Object.keys(DEFAULT_MARKET_GUIDELINES).map((m) => (
            <option key={m} value={m}>{m}</option>
          ))}
        </select>
      </div>

      {marketError && <p className="rounded border border-red-300 bg-red-100 px-3 py-2 text-sm font-semibold text-red-700">{marketError}</p>}

      {selectedMarket !== "Select Market" && DEFAULT_MARKET_GUIDELINES[selectedMarket] && (
        <div className="bg-blue-50 border border-blue-200 rounded p-4 text-sm text-blue-900">
          <h2 className="font-bold mb-2">{selectedMarket} QC Guidelines</h2>
          <div className="grid gap-2 sm:grid-cols-3">
            <p><span className="font-semibold">Expected Anchor:</span> {DEFAULT_MARKET_GUIDELINES[selectedMarket].exp_anchor}</p>
            <p><span className="font-semibold">Expected Ownership:</span> {DEFAULT_MARKET_GUIDELINES[selectedMarket].exp_ownership}</p>
            <p><span className="font-semibold">Expected Species:</span> {DEFAULT_MARKET_GUIDELINES[selectedMarket].exp_species}</p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-7 gap-3">
        <div className="bg-white p-3 rounded shadow border text-center">
          <p className="text-xs font-semibold text-gray-500 uppercase">Total Pole</p>
          <p className="text-xl font-bold text-gray-800 mt-1">{summaryStats.totalPoles}</p>
        </div>
        <div className="bg-white p-3 rounded shadow border text-center">
          <p className="text-xs font-semibold text-gray-500 uppercase">Total Note</p>
          <p className="text-xl font-bold text-gray-800 mt-1">{summaryStats.totalNotes}</p>
        </div>
        <div className="bg-white p-3 rounded shadow border text-center">
          <p className="text-xs font-semibold text-gray-500 uppercase">Total Anchor</p>
          <p className="text-xl font-bold text-gray-800 mt-1">{summaryStats.totalAnchors}</p>
        </div>
        <div className="bg-white p-3 rounded shadow border text-center">
          <p className="text-xs font-semibold text-gray-500 uppercase">Total Guy</p>
          <p className="text-xl font-bold text-gray-800 mt-1">{summaryStats.totalGuys}</p>
        </div>
        <div className="bg-blue-50 p-3 rounded shadow border border-blue-200 text-center">
          <p className="text-xs font-semibold text-blue-600 uppercase">Drop Poles</p>
          <p className="text-xl font-bold text-blue-700 mt-1">{summaryStats.numDropPoles}</p>
        </div>
        <div className="bg-green-50 p-3 rounded shadow border border-green-200 text-center">
          <p className="text-xs font-semibold text-green-600 uppercase">Passed</p>
          <p className="text-xl font-bold text-green-700 mt-1">{summaryStats.numPass}</p>
        </div>
        <div className="bg-red-50 p-3 rounded shadow border border-red-200 text-center">
          <p className="text-xs font-semibold text-red-600 uppercase">Errors</p>
          <p className="text-xl font-bold text-red-700 mt-1">{summaryStats.numError}</p>
        </div>
      </div>

      <div className="bg-white p-4 rounded shadow border space-y-4">
        <div className="flex items-center space-x-6">
          <input
            type="file"
            multiple
            accept=".xlsx, .xls, .csv, .json"
            onChange={handleFileUpload}
            className="text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-md file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
          />
          <button
            onClick={executeQCProcess}
            disabled={!Object.keys(fileData).length}
            className="px-6 py-2 bg-blue-600 text-white font-medium rounded shadow hover:bg-blue-700 disabled:bg-gray-300 transition-colors"
          >
            Run QC Check
          </button>
        </div>
        {statusMessage && <p className="text-sm text-blue-600 font-medium">{statusMessage}</p>}
      </div>

      {processedResults.length > 0 && (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <span className="text-sm font-semibold text-gray-600">
              Showing {displayed.length} of {processedResults.length} records
            </span>
            <label className="flex items-center space-x-2 text-sm font-medium text-gray-700">
              <input
                type="checkbox"
                checked={filterErrors}
                onChange={(e) => setFilterErrors(e.target.checked)}
                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
              />
              <span>Show Errors Only</span>
            </label>
          </div>

          <div className="overflow-x-auto bg-white rounded shadow border">
            <table className="min-w-full text-xs text-left border-collapse">
              <thead className="bg-gray-100 border-b uppercase font-semibold text-gray-700">
                <tr>
                  <th className="p-2 border">ACC</th>
                  <th className="p-2 border">HEIGHT</th>
                  <th className="p-2 border">CLASS</th>
                  <th className="p-2 border">HOA (FT)</th>
                  <th className="p-2 border">POLE ID</th>
                  <th className="p-2 border">MOD USER</th>
                  <th className="p-2 border">IQGEO LINK</th>
                  <th className="p-2 border">DETAILS</th>
                  <th className="p-2 border">CIRC CHECK</th>
                  <th className="p-2 border">HOA ERROR</th>
                  <th className="p-2 border">ANCHOR DETAILS</th>
                  <th className="p-2 border">OWNER</th>
                  <th className="p-2 border">SPECIES</th>
                </tr>
              </thead>
              <tbody className="divide-y text-gray-800">
                {displayed.map((row, idx) => (
                  <tr key={idx} className="hover:bg-gray-50">
                    <td className="p-2 border">{row.accessible}</td>
                    <td className="p-2 border">{row.height}</td>
                    <td className="p-2 border">{row.classVal}</td>
                    <td className="p-2 border">{row.hoa}</td>
                    <td className="p-2 border">{row.poleID}</td>
                    <td className="p-2 border font-medium text-gray-600">{row.modificationUser}</td>
                    <td className="p-2 border">
                      {row.iqLink ? (
                        <a
                          href={row.iqLink}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-blue-600 font-semibold underline hover:text-blue-800"
                        >
                          Go to Location in IQ
                        </a>
                      ) : (
                        <span className="text-gray-400">N/A</span>
                      )}
                    </td>
                    <td className="p-2 border whitespace-normal break-words max-w-[350px]">{row.poleDetails}</td>
                    <td className={`p-2 border font-semibold ${row.circCheck !== "MATCH" ? "bg-red-100 text-red-700" : ""}`}>
                      {row.circCheck}
                    </td>
                    <td className={`p-2 border font-semibold ${row.hoaCheck !== "MATCH" ? "bg-red-100 text-red-700" : ""}`}>{row.hoaCheck}</td>
                    <td className={`p-2 border font-semibold ${row.anchorDetails.includes("Incorrect") ? "bg-red-100 text-red-700" : ""}`}>{row.anchorDetails}</td>
                    <td className={`p-2 border font-semibold ${!row.isOwnerValid ? "bg-red-100 text-red-700" : ""}`}>{row.ownership}</td>
                    <td className={`p-2 border font-semibold ${!row.isSpeciesValid ? "bg-red-100 text-red-700" : ""}`}>{row.species}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <footer className="border-t pt-4 text-center text-xs text-gray-500">
        Developed by Shubham Srivastav | shubhamsri505@gmail.com
      </footer>
    </div>
  );
}